const groups = {};
async function collect(query, limit=100) {
  const r = search({query, limit});
  return r.items.map(i=>i.path);
}
const browser = collect("browser", 100);
const screen = collect("screen", 100);
const device = collect("device", 100);
const agent = collect("agent", 100);
const thread = collect("thread", 100);
const handoff = collect("handoff", 100);
return {
  browser: await browser,
  screen: await screen,
  device: await device,
  agent: await agent,
  thread: await thread,
  handoff: await handoff
};
